"""Work Roles and reviewed assistant actions through real browser/HTTP, disposable data.
AI responses are contract fixtures here. Live provider acceptance is recorded separately.
"""
import json,os,socket,sqlite3,subprocess,time,urllib.request
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'tests/.tmp/roles-ai-ui';OUT.mkdir(parents=True,exist_ok=True);DATA=OUT/str(time.time_ns());DATA.mkdir()
with socket.socket()as s:s.bind(('127.0.0.1',0));port=s.getsockname()[1]
base=f'http://127.0.0.1:{port}';checks=[];errors=[]
def check(ok,label):
    assert ok,label
    checks.append(label)
log=(OUT/'server.log').open('w',encoding='utf-8');server=subprocess.Popen([os.environ.get('LIFEOS_QA_PHP','php'),'-S',f'127.0.0.1:{port}','-t','public','public/index.php'],cwd=ROOT,env=dict(os.environ,LIFEOS_DATA_DIR=str(DATA)),stdout=log,stderr=log,creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
try:
    for _ in range(100):
        try:urllib.request.build_opener(urllib.request.ProxyHandler({})).open(base+'/health',timeout=2).close();break
        except OSError:time.sleep(.1)
    db=sqlite3.connect(DATA/'lifeos.db');db.executemany('INSERT INTO settings(key,value) VALUES (?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',[('name','QA user'),('onboarding_complete','1')]);db.commit()
    with sync_playwright()as pw:
        browser=pw.chromium.launch(headless=True);page=browser.new_page(viewport={'width':1365,'height':900},reduced_motion='reduce');page.on('pageerror',lambda e:errors.append(str(e)))
        page.goto(base+'/roles');page.locator('form[action="/roles/templates"] button').click();expect(page.locator('select[name=role] option')).to_have_count(6);check(db.execute('SELECT COUNT(*) FROM work_roles').fetchone()[0]==6,'Default role button creates six editable roles')
        count=db.execute('SELECT COUNT(*) FROM work_tasks').fetchone()[0];page.reload();check(db.execute('SELECT COUNT(*) FROM work_tasks').fetchone()[0]==count,'Today reload does not duplicate responsibilities')
        role=db.execute('SELECT id FROM work_roles ORDER BY id').fetchone()[0];task=db.execute('SELECT id FROM work_tasks WHERE role_id=? ORDER BY id',[role]).fetchone()[0]
        timer=page.locator('form[action="/roles/timer/start"]');timer.locator('select[name=task_id]').select_option(str(task));timer.locator('button').click();expect(page.locator('[data-role-timer]')).to_be_visible();check(db.execute('SELECT COUNT(*) FROM role_time_logs WHERE ended_at IS NULL').fetchone()[0]==1,'Role/task timer starts')
        page.locator('form[action="/roles/timer/stop"] button').click();expect(page.locator('[data-role-timer]')).to_have_count(0);check(db.execute('SELECT COUNT(*) FROM role_time_logs WHERE ended_at IS NULL').fetchone()[0]==0,'Role timer stops')
        status=page.locator(f'form[action="/roles/tasks/{task}/status"]');status.locator('select').select_option('done');status.locator('button').click();expect(page.get_by_text('Work task updated.',exact=True)).to_be_visible();check(db.execute('SELECT status,done_at FROM work_tasks WHERE id=?',[task]).fetchone()[0]=='done','Role task completion persists')
        daily=page.locator('form[action="/roles/daily"]');daily.locator('[name=did]').fill('Reviewed code');daily.locator('[name=blocked]').fill('Missing example');daily.locator('[name=next]').fill('Ask the team');daily.locator('button').click();expect(page.get_by_text('Daily work log saved.',exact=True)).to_be_visible();page.locator('form[action$="/lesson"] button').click();expect(page.get_by_text('Reflection linked to Lessons.',exact=True)).to_be_visible();check(db.execute('SELECT COUNT(*) FROM lessons').fetchone()[0]==1,'Daily log links to a learning/failure record')
        page.goto(base+'/roles?view=week');income=page.locator('form[action="/roles/income"]').first;income.locator('..').locator('summary').click();income.locator('input[name=amount]').fill('125.50');income.locator('button:not([type=button])').click();expect(page.get_by_text('Received income recorded once through Money.',exact=True)).to_be_visible();check(db.execute('SELECT amount FROM income').fetchone()[0]==125.5,'Confirmed role income reaches Money')
        page.add_init_script("window.chrome=window.chrome||{};window.__bridge=[];window.chrome.webview={postMessage:m=>window.__bridge.push(m),addEventListener:()=>{},removeEventListener:()=>{}}")
        page.goto(base+'/assistant');page.set_viewport_size({'width':450,'height':720});expect(page.locator('[data-welcome]')).to_be_visible();check(page.locator('select,input[type=checkbox]').count()==0,'Normal chat has no model inventory or repeated consent checkboxes');check('OpenCode' not in page.locator('body').inner_text() and 'Free model' not in page.locator('body').inner_text(),'Product identifies itself as LifeOS AI')
        expect(page.get_by_text('Messages are processed online.',exact=True)).to_be_visible();check(page.get_by_text('Messages are processed online.',exact=True).is_visible(),'Online processing disclosure is visible beside Send')
        page.screenshot(path=str(OUT/'assistant-welcome.png'));page.locator('[data-suggestion]').first.click();expect(page.locator('[name=message]')).not_to_have_value('');check(page.locator('article').count()==0,'Suggestion prepares a message for review')
        form=page.locator('[data-assistant-composer]');form.locator('[name=message]').fill('Create a reviewed task');form.locator('button').click();expect(page.locator('.chat-pending')).to_be_visible();page.screenshot(path=str(OUT/'assistant-thinking.png'))
        jobs=list((DATA/'ai/jobs').glob('*.json'));check(len(jobs)==1,'One send creates one background request');file=jobs[0];chat_id=file.stem;job=json.loads(file.read_text(encoding='utf-8'));check(not job['context'] and job['auto_model'] and 'model' not in job,'Model selection is automatic and personal totals stay private');check(page.evaluate('window.__bridge.some(m=>m.type==="lifeos-ai-job")'),'Pending chat reaches native worker bridge')
        before=db.execute('SELECT COUNT(*) FROM tasks').fetchone()[0];job['status']='complete';job['answer']=json.dumps({'answer':'## A useful next step\nReview **one task** before adding it.\n<script>unsafe()</script>','actions':[{'action':'add_task','title':'Review suggested task','due':'2099-01-05'}]});file.write_text(json.dumps(job),encoding='utf-8');expect(page.locator('[data-action-form]')).to_be_visible();check(db.execute('SELECT COUNT(*) FROM tasks').fetchone()[0]==before,'AI answer does not execute a write');check(page.locator('article script').count()==0 and page.locator('article strong').count()>0,'Answer is safely formatted without executing HTML')
        page.screenshot(path=str(OUT/'assistant-review.png'));apply=page.locator('[data-action-form]').first;apply.locator('[name=title]').fill('User-reviewed task');apply.locator('button').click();expect(page.get_by_text('Added to Planner',exact=False)).to_be_visible();check(db.execute('SELECT COUNT(*) FROM tasks WHERE title=?',['User-reviewed task']).fetchone()[0]==1,'Only confirmed reviewed task is created');page.reload();expect(page.locator('.action-applied')).to_be_visible();check(page.locator('[data-action-form]').count()==0,'Applied action remains confirmed after reopening')
        page.locator('[name=message]').fill('What next?');page.locator('[name=message]').press('Enter');expect(page.locator('.chat-pending')).to_be_visible();latest=next(p for p in (DATA/'ai/jobs').glob('*.json') if p.stem!=chat_id);follow=json.loads(latest.read_text(encoding='utf-8'));check(len(follow['conversation'])==2,'Follow-up has this chat history');follow['status']='failed';follow['error']='opencode confidential provider quota';latest.write_text(json.dumps(follow),encoding='utf-8');expect(page.locator('.chat-error')).to_be_visible();check('confidential provider' not in page.locator('body').inner_text(),'Provider errors remain internal');page.screenshot(path=str(OUT/'assistant-unavailable.png'));page.locator('.text-button').click();expect(page.locator('[name=message]')).to_have_value('What next?')
        page.emulate_media(color_scheme='dark');page.screenshot(path=str(OUT/'assistant-dark.png'));check(page.locator('html').evaluate('e=>getComputedStyle(e).colorScheme')=='dark','Chat follows dark theme');page.emulate_media(color_scheme='light');page.locator('[data-new-chat]').click();expect(page.locator('[data-welcome]')).to_be_visible();check(page.locator('article').count()==0,'New chat clears the active conversation')
        for lang in ['si','ta']:
            db.execute("INSERT INTO settings(key,value) VALUES ('locale',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",[lang]);db.commit();page.reload();page.screenshot(path=str(OUT/f'assistant-{lang}.png'));check(page.locator('html').get_attribute('lang')==lang,'Assistant uses '+lang+' locale')
        db.execute("UPDATE settings SET value='en' WHERE key='locale'");db.commit()
        for route,label in [('/roles','roles-today'),('/roles?view=week','roles-week'),('/assistant','assistant-empty')]:
            page.goto(base+route)
            for width in [1365,390]:
                page.set_viewport_size({'width':width,'height':900});page.screenshot(path=str(OUT/f'{label}-{width}.png'),full_page=True);check(page.evaluate('document.documentElement.scrollWidth<=innerWidth+1'),f'{label} fits {width}')
        page.set_viewport_size({'width':360,'height':460});page.goto(base+'/assistant');check(page.locator('[data-assistant-composer]').is_visible() and page.evaluate('document.documentElement.scrollWidth<=innerWidth'),'Small assistant keeps composer visible without horizontal scrolling');page.screenshot(path=str(OUT/'assistant-compact.png'));page.keyboard.press('Escape');check(page.evaluate('window.__bridge.some(m=>m.action==="hide")'),'Escape hides native assistant');check(not errors,f'No browser script errors: {errors}');browser.close()
    (OUT/'results.json').write_text(json.dumps({'checks':checks,'errors':errors},indent=2),encoding='utf-8');print(f'{len(checks)} role/AI UI checks passed. Evidence: {OUT}')
finally:server.terminate();server.wait(timeout=10);log.close()
